136:   static approveStage(cr, approverId, approverRole, comments = '') {
137:     if (cr.status !== ChangeStatuses.PENDING_APPROVAL && cr.status !== ChangeStatuses.ESCALATED) {
138:       throw new Error(`ILLEGAL_TRANSITION: Cannot approve change request in status ${cr.status}`);
139:     }
140: 
141:     // Rule BR-001: Self-approval ban
142:     if (cr.requesterId === approverId) {
143:       const err = new Error('SELF_APPROVAL_VIOLATION: Requesters cannot approve their own change requests');
144:       err.code = 'SELF_APPROVAL_VIOLATION';
145:       throw err;
146:     }
147: 
148:     const currentStage = cr.stages[cr.activeStageIndex];
149:     if (!currentStage) {
150:       throw new Error('STAGE_ERROR: No active pending approval stage found');
151:     }
152: 
